// Monta o prompt para a IA a partir do resumo gerado pelo pipeline Python
const fileContent = $input.first().binary.data
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf-8')
  : $input.first().json.data;

const summary = JSON.parse(fileContent);

const systemPrompt = `Você é um analista sênior de políticas educacionais internacionais, atuando para um organismo multilateral. Sua função é interpretar indicadores educacionais de diferentes países e produzir inteligência acionável para tomadores de decisão — não apenas descrever números.

Regras obrigatórias:
- Nunca apenas repita ou resuma os números recebidos; sempre acrescente interpretação, hipóteses causais plausíveis e implicações práticas.
- Identifique explicitamente: países que mais evoluíram, países estagnados ou em regressão, países com maior investimento relativo, países com melhores indicadores absolutos.
- Para cada padrão identificado, proponha possíveis explicações (ex: crises econômicas, reformas educacionais, mudanças demográficas) deixando claro quando é hipótese e não fato comprovado pelos dados.
- Termine com recomendações concretas e priorizadas.
- Seja direto, use linguagem executiva, evite jargão técnico desnecessário.`;

const userPrompt = `Abaixo está um resumo estruturado (JSON) com indicadores educacionais de múltiplos países, já processados (rankings, crescimento, agregações).

Gere um RELATÓRIO EXECUTIVO em Markdown com as seções:

1. Panorama geral (2-3 parágrafos)
2. Países em destaque (maior evolução, com hipóteses do porquê)
3. Países estagnados ou em regressão (com hipóteses do porquê)
4. Investimento vs. resultado (quem investe mais e o retorno aparente)
5. Comparações relevantes entre países
6. Recomendações (priorizadas, acionáveis)

Dados:
\`\`\`json
${JSON.stringify(summary, null, 2)}
\`\`\``;

return [{
  json: {
    model: 'claude-sonnet-4-6',
    max_tokens: 4000,
    system: systemPrompt,
    messages: [{ role: 'user', content: userPrompt }]
  }
}];

// Extrai o texto do relatório da resposta da API do Claude
const response = $input.first().json;
const textBlocks = (response.content || []).filter(b => b.type === 'text');
const reportText = textBlocks.map(b => b.text).join('\n');

const timestamp = new Date().toISOString().slice(0, 10);
const header = `# Relatório Executivo - Indicadores Educacionais\n\n_Gerado automaticamente em ${timestamp}_\n\n---\n\n`;

return [{
  json: {
    fileName: `executive_report_${timestamp}.md`,
    content: header + reportText
  }
}];
